import{_ as s,h as i,i as e,c as o,v as t,p as n,x as l,m as p,e as d,S as _}from"./chunks/framework.Dvtg8yj2.js";const u=JSON.parse('{"title":"视频作为带位姿的图像序列","description":"","frontmatter":{"title":"视频作为带位姿的图像序列","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/atlas-video-as-frames.md","filePath":"llm/atlas-video-as-frames.md","lastUpdated":1788454257000}'),m={name:"llm/atlas-video-as-frames.md"};function h(k,a,A,P,c,E){const r=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="视频作为带位姿的图像序列" tabindex="-1">视频作为带位姿的图像序列 <a class="header-anchor" href="#视频作为带位姿的图像序列" aria-label="Permalink to &quot;视频作为带位姿的图像序列&quot;">​</a></h1><div class="epigraph"><p>视频不是另一种需要单独词表的模态；它是按时间排列、每张都钉着相机位姿的图像，空间上下文沿轨迹被查询。</p><footer>—— World Labs Atlas：videos are represented as sequences of images，每张图条件于显式相机</footer></div><p>多模态模型常把视频做成第三套编码器：时间补丁、3D 卷积、或沿帧的独立 ViT 再加时间注意力。Atlas 的公开定义更省：视频就是图像序列，每张图像带位姿。于是生成一分钟镜头、在真实视频上做 reframing、从录像重建点云，都是在同一套「带 \\(P\\) 的图」上改序列模板，而不是切换到另一个骨干。本篇讲这个表示选择的后果，以及它与「无位姿的帧堆」差在哪里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若视频是无位姿的 RGB 堆 \\(I_{1:T}\\)，模型看见的运动混合了相机运动与场景运动，无法单独控制其中一项。电影运镜、机器人沿轨迹看、子弹时间（时间几乎冻结、相机在空间里绕）要求把 \\(t\\) 与 \\(P\\) 拆开：时间可以停，位姿仍可改。没有每帧 \\(P\\)，子弹时间只能靠「转圈」的文本去碰。</p><p>另一个问题是长度。一分钟 1440p 若当单一 4D 张量一次扩散，内存与注意力会按 \\(T\\times H\\times W\\) 爆。自回归按元素（帧或潜帧）推进，KV 可以缓存已经生成的帧，这与 LLM 解码同构。把视频定义为图像序列，是为了让 <a href="/llm/atlas-ardt">ARDT</a> 的元素级时间轴等于帧，而不是另发明一套视频 token 语法。</p><h3 id="帧率与位姿必须一起定义时间" tabindex="-1">帧率与位姿必须一起定义时间 <a class="header-anchor" href="#帧率与位姿必须一起定义时间" aria-label="Permalink to &quot;帧率与位姿必须一起定义时间&quot;">​</a></h3><p>只有帧下标 \\(k=1,\\ldots,T\\) 时，「相邻」可能是 1/24 秒也可能是 1/3 秒，运动速度不可迁移。位姿序列 \\(P_k\\) 给出空间上的采样，但若缺少时间戳，动态物体的速度仍不确定。Atlas 博客把空间与时间并称（space-time simulation），但视频表示的句子只明确了「图像序列 + 每帧相机」。时间戳是否作为原生标量，没有写成与 \\(P\\) 同级的字段表。能确定的最小结构是：</p> \\[\\text{video}=\\bigl\\{(I_k,P_k)\\bigr\\}_{k=1}^{T}, \\]<p>动态要靠相邻 \\(I_k\\) 的变化来学，而不是单独一条物理状态向量。</p><p><span class="marginnote">Qwen-VL 一类 VLM 把视频当视觉 token 进语言模型，目标是理解而不是按任意 \\(P\\) 出新视。Atlas 的序列是生成与重建共用的世界接口。不要把「视频 token」和「带位姿的图像序列」写成同一个设计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生成长视频：少量参考图（博客写一到六张）加上手绘相机路径，沿 \\(k\\) 自回归出 \\((I_k,P_k)\\) 中的 \\(I_k\\)（\\(P_k\\) 由用户指定）。因为 \\(P_k\\) 是原生的，路径可以按导演意图停、绕、升，而不改参考图。同一组参考可以生成许多条不同轨迹，场景应保持一致——这是空间上下文在时间展开上的用法。</p><p>消费真实视频时，每帧仍视为带位姿的图（位姿来自标定或多视几何）。于是可以：估深度再融合成点云；冻结时间、在多机位之间插值做 bullet time；给机器人仿真沿新轨迹出 RGB 与深度。这些任务不需要「视频专家头」，只要序列里元素类型是图像或深度，条件里有 \\(P\\)。</p>',14)),(e(),n(_,null,{default:l(()=>[d(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%8F%82%E8%80%83%E5%9B%BE%20%2B%20%E4%BD%8D%E5%A7%BF%22%5D%20--%3E%20X%5B%22%E7%A9%BA%E9%97%B4%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20P%5B%22%E8%B7%AF%E5%BE%84%20P_1%20...%20P_T%22%5D%20--%3E%20AR%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%E4%B8%8B%E4%B8%80%E5%B8%A7%22%5D%0A%20%20X%20--%3E%20AR%0A%20%20AR%20--%3E%20F%5B%22I_k%22%5D%0A%20%20F%20--%3E%20X%0A%20%20F%20--%3E%20OUT%5B%22%E8%A7%86%E9%A2%91%20%3D%20%E5%B8%A6%20P%20%E7%9A%84%E5%9B%BE%E5%83%8F%E5%BA%8F%E5%88%97%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="时间冻结与空间继续" tabindex="-1">时间冻结与空间继续 <a class="header-anchor" href="#时间冻结与空间继续" aria-label="Permalink to &quot;时间冻结与空间继续&quot;">​</a></h3><p>Bullet time 把时间导数压低、把 \\(\\partial P/\\partial k\\) 拉大：几台真实相机给出同一时刻附近的观测，查询却是从未架设过的 \\(P\\)。表示成带位姿的图像后，这只是「上下文里若干几乎同时的 \\((I_j,P_j)\\)，查询一个新的 \\(P_\\star\\)」。若视频只是时间 token，模型容易按时间外推成下一毫秒，而不是按空间绕到侧面。官方示例强调三到五台手机即可 reframing，依据正是多视空间上下文，而不是高帧率。</p><p><span class="marginnote">动态场景里「同一时刻」需要时间对齐。多机位若时间码差一帧，空间上正确的 \\(P\\) 也会对上错误的物体姿态。这是采集问题，模型不能从表示定义里自动消失。</span></p><h3 id="潜帧而不是像素帧" tabindex="-1">潜帧而不是像素帧 <a class="header-anchor" href="#潜帧而不是像素帧" aria-label="Permalink to &quot;潜帧而不是像素帧&quot;">​</a></h3><p>1440p 像素不能直接当 Transformer 元素。Rombach 的 LDM 把每帧压成 \\(z_k\\)，序列在潜网格上自回归，解码才回到像素。于是「图像序列」在计算图上是 \\(\\{(z_k,P_k)\\}\\)。\\(P_k\\) 仍必须与 \\(z_k\\) 对齐，否则潜空间里的空间上下文是瞎的。潜压缩会丢掉解码器补不回的高频，长镜头的细字、远景栅栏会先糊；这是表示代价，不是位姿没喂进去。</p><p><span class="marginnote">不要把「图像序列」理解成每帧独立扩散再拼接。自回归要求 \\(I_k\\) 看见 \\(I_{&lt;k}\\)，否则时间一致性全靠 \\(P_k\\) 的光滑，动态物体会闪。序列定义给出的是接口，不是已经保证了帧间锁相。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自回归沿 \\(k\\) 走时，已经生成的 \\((I_{&lt;k},P_{&lt;k})\\) 进入 KV，成为后续帧的空间记忆。这与 RTFM 的 posed frames 相同家族：记忆的索引可以按位姿取近邻，而不必把 \\(T\\) 分钟全部放进窗口。Atlas 是否在长视频里做了与 RTFM 相同的 context juggling，博客没写；不要默认已实现。能写的机制是：帧是元素，位姿是条件，扩散在帧内去噪。</p><p>潜空间（Rombach LDM）让每帧是压缩后的 \\(z_k\\) 而不是原图像素，序列长度按潜网格算而不是按 1440p 像素。整流流再在 \\(z\\) 里积分。于是「视频」在计算图上是潜帧序列 + 位姿序列，解码才变成像素。这解释了为何同一架构既能出短图，也能出长镜头：差在元素个数，不在模态种类。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>一分钟、1440p 是展示上限量级，不是实时交互规格。帧间闪烁、长程漂移、动态物体的物理错误，都不会因为「视频=图像序列」而消失；序列只提供接口。无位姿的网络视频当训练数据时，必须先估 \\(P\\)，估错则空间上下文被污染。纯时间视频模型在「描述性运镜 + 故事」上可能更顺，因为它们优化的就是那种边缘分布；Atlas 的优势在可指定 \\(P\\) 的路径，不在自动剪辑叙事。</p><p>不要发明 Atlas 的帧率、是否用 3D VAE、时间注意力窗口。出处：World Labs Atlas 博客关于 multimodal 的那几句，以及可控长视频、reframing 的示例。对照 <a href="/llm/video-tokens">视频 token 与时间采样</a> 只为说明 VLM 压缩问题，不是 Atlas 用了 Qwen 的 MRoPE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Atlas 把视频定义为带显式相机位姿的图像序列，而不是单独一套视频模态。</li><li>生成、reframing、沿轨迹仿真，都是对 \\((I_k,P_k)\\) 序列换条件与长度。</li><li>拆开时间与位姿，才能做时间冻结、空间绕行的子弹时间。</li><li>自回归按帧推进，以便 KV 缓存与可变 \\(T\\)；帧内仍是潜空间整流流。</li><li>长镜头的漂移与动态物理不由这一定义单独解决；一分钟 1440p 是展示而非实时保证。</li><li>出处：World Labs Atlas 博客。无帧级架构 arXiv。</li></ul>',14))])}const B=s(m,[["render",h]]);export{u as __pageData,B as default};
